/* Estilo para la barra lateral de BetterDocs */
.betterdocs-elementor-single-sidebar {
    max-height: calc(100vh - 90px); /* Ajusta la altura máxima según tus necesidades */
    overflow-y: auto; /* Agrega el desplazamiento vertical cuando sea necesario */
}

.elementor-button-text {
    flex-grow: 1;
    order: 10;
    display: flex;
}

/* Estilo para ajustar la altura del icono de categoría en la barra lateral */
.betterdocs-category-icon .betterdocs-category-icon-img {
    height: 50px !important;
    width: auto;
}

/* Estilo para la caja de categoría en el diseño 2 de Elementor */
.elementor-widget-betterdocs-category-box .betterdocs-category-box-wrapper.betterdocs-elementor.el-layout-2 .betterdocs-single-category-wrapper .betterdocs-category-icon {
    border-right: 0px solid #f1f1f8 !important;
    padding-top: 12px! important;
    padding-right: 8px !important;
    padding-bottom: 12px !important;
    padding-left: 8px !important;
}

/* Estilo para la cabecera de categoría en el diseño 2 de Elementor */
.elementor-widget-betterdocs-category-box .betterdocs-category-box-wrapper.betterdocs-elementor.el-layout-2 .betterdocs-single-category-wrapper .betterdocs-category-header-inner {
    display: flex;
    flex-direction: row;
    justify-content: flex-start;
    padding-right: 3px  !important;
    position: relative;
    flex-wrap: nowrap;
    align-items: center;
}

/* Estilo para los enlaces de subcategorías en páginas de conocimiento individual */
.single-kb .betterdocs-articles-list .betterdocs-nested-category-wrapper .betterdocs-nested-category-title a,
.single-kb .betterdocs-entry-body .betterdocs-nested-category-wrapper .betterdocs-nested-category-title a {
    font-family: "Poppins", Sans-serif;
    color: #000000 !important; /* Intenta añadir !important */
    font-size: 14px;
    font-weight: 600;
}

/* Estilo para los enlaces en las categorías y artículos */
.betterdocs-single-category-wrapper .betterdocs-single-category-inner .betterdocs-articles-list li a,
.betterdocs-single-category-wrapper .betterdocs-single-category-inner .betterdocs-entry-body li a {
    text-decoration: none; /* Quita la subrayado predeterminado */
    font-family: "Poppins", Sans-serif;
    color: #000000 !important; /* Cambia el color a negro */
    font-size: 14px !important;
    font-weight: 600; /* Ajusta el peso de la fuente */
}

/* Estilo para el título y color en las categorías y artículos 
.betterdocs-category-header-inner .betterdocs-category-title {
    color: #000000 !important; /* Cambia el color del título a negro */


.elementor-button-icon svg {
    width: 2em;
    height: auto;
    o: ;
}

/* Establecer el tamaño del icono al cargar la página */
.betterdocs-category-collapse {
    width: 20px !important;
    height: 20px !important;
}

/* Evitar que el tamaño del icono se vea afectado después de cargar la página */
.betterdocs-category-collapse svg {
    width: 100% !important;
    height: 100% !important;
}

/* Establecer el tamaño del icono al cargar la página - Selector específico */
div .st0 {
    width: 20px;
    height: 20px;
}

/* Estilo para la cuadrícula de categorías con desplazamiento vertical */
.betterdocs-category-grid-wrapper .betterdocs-category-grid-inner-wrapper.masonry>.betterdocs-single-category-wrapper {
    height: 305px;
    overflow-y: auto; /* Agrega un desplazamiento vertical si el contenido excede la altura especificada */
}

/* Estilo para el pie de página pegajoso */
.betterdocs-footer {
    position: sticky;
    bottom: 0;
    background-color: #fff;
   padding: 9px 20px 7px; /* Espaciado interno para un aspecto más agradable */
    z-index: 2;
    transition: background-color 0.3s ease; /* Agregar una transición suave para el cambio de color de fondo */
}

/* Estilo para los enlaces en el pie de página */
.betterdocs-footer a {
    text-decoration: none;
    color: #3498db; /* Cambiar el color del enlace */
    font-weight: bold;
}

/* Estilo al pasar el ratón sobre los enlaces en el pie de página */
.betterdocs-footer a:hover {
    color: #2980b9; /* Cambiar el color del enlace al pasar el ratón */
}

/* Estilo para la cabecera de categoría pegajosa en la página 
.betterdocs-category-header {
    position: sticky;
    top: 0;
    background-color: #fff; /* Puedes ajustar el color de fondo según tus preferencias */
    z-index: 1;
}

/* Estilo adicional para la parte interna de la cabecera de categoría 
.betterdocs-category-header-inner {
    /* Estilos adicionales según sea necesario */
}

______________________________
/* Estilo para la barra de desplazamiento en Firefox */
* {
  scrollbar-width: thin;
  scrollbar-color: #f2f4f7;
}

/* Estilo para la barra de desplazamiento en Chrome, Edge y Safari */
*::-webkit-scrollbar {
  width: 10px;
}

*::-webkit-scrollbar-track {
  background: #f2f4f7;
}

*::-webkit-scrollbar-thumb {
  background-color: #a9abaede;
  border-radius: 5px;
  border: 2px solid #f2f4f7;
}

/**::-webkit-scrollbar-thumb:hover {
  background-color: #a9abaede;
  border-radius: 5px;
  border: 2px solid #f2f4f7;
}*/
____________________________
/* Estilo al pasar el ratón sobre los enlaces en el pie de página */
.betterdocs-footer a:focus, .betterdocs-footer a:hover, .betterdocs-footer button:focus, .betterdocs-footer button:hover {
    background-color: #ffffff !important;
    border-color: #273272 !important;
    color: #273272 !important;
}

.betterdocs-category-header {
    position: sticky;
    top: 0;
    background-color: #fff;
    z-index: 1;
    border-radius: 20px !important;
}


.betterdocs-footer a, .betterdocs-footer button {
    align-items: center;
    border: 1px solid #273272 !important;
    border-radius: 7px !important;
    color: #ffffff !important;
    display: inline-flex !important;
    font-size: 14px !important;
    gap: 5px;
    padding: 4px 15px !important;
    text-decoration: none;
    transition: all .3s;
    background-color: #273272;
}

.betterdocs-category-title:not(:has(a)) {
    color: #000000 !important;
    font-size: 20px;
    line-height: 1;
    margin-bottom: 0;
    margin-top: 0;
    text-decoration: none;
}

/* Estilo al seleccionar una publicación */
.elementor-355 .elementor-element.elementor-element-2618ddc .betterdocs-category-grid-wrapper .betterdocs-category-grid-inner-wrapper .betterdocs-single-category-wrapper.active .betterdocs-category-header {
    background-color: #5A94FF3B;
    border-color: #528fff !important;
    border-right: 3px solid #5a94ff !important;
}


.elementor-355 .elementor-element.elementor-element-2618ddc .betterdocs-single-category-wrapper.active .betterdocs-single-category-inner .betterdocs-articles-list .betterdocs-nested-category-list li a:active {
    /* Tu estilo para el enlace del artículo activo aquí */
    background-color: #5A94FF3B !important;
    border-color: #528fff !important;
    border-right: 3px solid #5a94ff !important;
}


.elementor-355 .elementor-element.elementor-element-2618ddc .betterdocs-single-category-wrapper .betterdocs-single-category-inner .betterdocs-articles-list .betterdocs-nested-category-list li a.active-article {
    background-color: #5A94FF3B;
    border-color: #528fff !important;
    border-right: 3px solid #5a94ff !important;
}


.menu-container {
      display: flex;
      align-items: center;
      color: #2399f3;
      font-size: 16px;
}

.menu-icon {
      width: 25px;
      height: 25px;
      margin-right: 5px;
}

.menu-text {
      color: #2399f3;
    }
.menu-text:hover  {
      color: #000000;
}

.elementor-31170 .elementor-element.elementor-element-d9cb877 .elementskit-navbar-nav > li > a .elementskit-submenu-indicator {
    color: #528fff;
    fill: #101010;
}


.ekit-btn-wraper a.elementskit-btn {
    text-align: left;
    display: flex;
    align-items: left; /* Esto puede ser necesario dependiendo de la estructura actual */
    justify-content: space-between; /* Esto coloca el contenido a la izquierda y el icono a la derecha */
}

.ekit-btn-wraper a.elementskit-btn i {
    margin-left: 5px; /* Ajusta la distancia del icono al borde derecho */
}

