/* Establece el tamaño del icono SVG a 24x24 píxeles y lo alinea verticalmente al centro */
.menu-icon {
  width: 24px;
  height: 24px;
  vertical-align: middle;
}

/* Estilo para el texto del menú */
/* Añade un margen a la izquierda del texto para separar del icono y lo alinea verticalmente al centro */
.menu-text {
  margin-left: 8px;
  vertical-align: middle;
}
