document.addEventListener('DOMContentLoaded', function() {
 var articles = document.querySelectorAll('.elementor-355 .elementor-element.elementor-element-2618ddc .betterdocs-single-category-wrapper.active .betterdocs-single-category-inner .betterdocs-articles-list .betterdocs-nested-category-list li a');

 articles.forEach(function(article) {
 article.addEventListener('click', function() {
 // Eliminamos la clase de todos los enlaces
 articles.forEach(function(a) {
 a.classList.remove('active-article');
 });

 // Agregamos la clase al enlace del artículo activo
