<select id="baseSelector">
 <option value="administrativos">Administrativos</option>
 <option value="docentes">Docentes</option>
 <option value="estudiantes">Estudiantes</option>
</select>

<!-- Contenedores para mostrar la información de cada base -->
<div id="administrativosContainer">
 <!-- Shortcode para mostrar la información de BetterDocs para administrativos -->
 [betterdocs_multiple_kb_list terms="" kb_slug="administrativos" title_tag="h2"]
</div>

<div id="docentesContainer" style="display:none">
 <!-- Shortcode para mostrar la información de BetterDocs para docentes -->
 [betterdocs_multiple_kb_list terms="" kb_slug="docentes" title_tag="h2"]
</div>

<div id="estudiantesContainer" style="display:none">
 <!-- Shortcode para mostrar la información de BetterDocs para estudiantes -->
 [betterdocs_multiple_kb_list terms="" kb_slug="estudiantes" title_tag="h2"]
</div>

<!-- Script para gestionar el cambio en la selección de la base -->
<script>
 document.getElementById('baseSelector').addEventListener('change', function() {
 // Ocultar todos los contenedores
 document.getElementById('administrativosContainer').style.display = 'none';
 document.getElementById('docentesContainer').style.display = 'none';
 document.getElementById('estudiantesContainer').style.display = 'none';

 // Obtener el valor seleccionado
 var selectedBase = this.value;

 // Mostrar el contenedor correspondiente a la base seleccionada
 document.getElementById(selectedBase + 'Container').style.display = 'block';
 });
</script>
